"""Read Gateway responses generated by Sarex UI; never extract or replay credentials."""

import json
import re
import sys
import time
from collections import deque
from datetime import UTC, datetime
from urllib.parse import parse_qsl, urlsplit

from sarex_loader.api_models import valid_id
from sarex_loader.folder_resolver import tree_component
from sarex_loader.safety import ValidationError

UI_ORIGIN = 'https://lk.sarex.io'
API_ORIGIN = 'https://api.sarex.io'
LOGIN_HOST = 'login.sarex.io'
MODULE_HOST = 'modules.sarex.io'


def browser_request_allowed(method, url):
    """Browser auth is user-operated. Every resource mutation is blocked.

    No Python auth client, storage_state, HAR, tracing, cookies or header copying.
    The temporary browser profile is owned and cleaned up by Playwright.
    """
    try:
        u = urlsplit(url)
        if (u.scheme != 'https' or u.username is not None or u.password is not None
                or u.port not in (None, 443)):
            return False
        # Observed UI microfrontend. Without remoteEntry.js the navigation menu
        # renders but Documentation never initializes and no Gateway GET follows.
        # This exception is static assets only, not another API/auth origin.
        if u.hostname == MODULE_HOST:
            query = parse_qsl(u.query, keep_blank_values=True)
            cache_stamp = (not query or (len(query) == 1 and query[0][0] == 'ts'
                           and re.fullmatch(r'[0-9]{1,16}', query[0][1]) is not None))
            return (method in {'GET', 'HEAD', 'OPTIONS'} and cache_stamp
                    and '..' not in u.path.split('/')
                    and re.fullmatch(
                        r'/documentations/static/[A-Za-z0-9_./-]+\.(?:js|css|woff2?|svg|png)',
                        u.path) is not None)
        if u.hostname not in {'lk.sarex.io', 'api.sarex.io', LOGIN_HOST}:
            return False
        return method in {'GET', 'HEAD', 'OPTIONS'} or (
            method == 'POST' and u.hostname == LOGIN_HOST)
    except ValueError:
        return False


def gateway_response_matches(response, disk_id, folder_id):
    try:
        u = urlsplit(response.url)
        return (response.request.method == 'GET' and u.scheme == 'https'
                and u.netloc == 'api.sarex.io'
                and u.path == f'/gateway/api/v1/disks/{disk_id}/documents'
                and parse_qsl(u.query, keep_blank_values=True) in (
                    [('child_id', str(folder_id))], [('parent_id', str(folder_id))]))
    except (ValueError, AttributeError):
        return False


def scoped_browser_request_allowed(request, disk_id, folder_id):
    if not browser_request_allowed(request.method, request.url):
        return False
    u = urlsplit(request.url)
    # App-wide disk metadata may load breadcrumbs, but document tree navigation
    # is restricted to the selected folder. Never expand another working branch.
    if '/gateway/api/' in u.path and re.search(r'/disks/[^/]+/documents/?$', u.path):
        return (u.netloc == 'api.sarex.io'
                and u.path == f'/gateway/api/v1/disks/{disk_id}/documents'
                and parse_qsl(u.query, keep_blank_values=True) in (
                    [('child_id', str(folder_id))], [('parent_id', str(folder_id))]))
    return True


def collect_paths(paths, index, fetch, *, max_folders):
    """Traverse a trie of required paths: one UI navigation per distinct parent.

    Refresh parents even if a previous response happened to include their descendants.
    This observes new siblings/months and does not confuse breadcrumbs with coverage.
    """
    roots = {}
    for root, parts in paths:
        if (not valid_id(root) or type(parts) is not tuple or len(parts) > 32
                or any(not tree_component(p) for p in parts)):
            raise ValidationError('TREE_PATH_INVALID')
        node = roots.setdefault(root, {})
        for part in parts:
            node = node.setdefault(part, {})
    queue = deque(sorted(roots.items()))
    visited, failed = set(), set()
    while queue:
        parent, wanted = queue.popleft()
        if parent not in visited:
            if len(visited) >= max_folders:
                raise ValidationError('TREE_FOLDER_BUDGET_EXCEEDED')
            if fetch(parent) is False:
                failed.add(parent)
            visited.add(parent)
        if parent in failed:
            continue
        for name, nested in sorted(wanted.items()):
            result = index.child(parent, name)
            if result.folder_id is not None:
                queue.append((result.folder_id, nested))
    return len(visited)


def collect_browser_tree(source, paths, index):
    if source.browser_mode == 'extension':
        return collect_extension_tree(source, paths, index)
    if not paths:
        return
    # Import is inert for ordinary dry-run/JSON users; no mandatory browser dependency.
    try:
        from playwright.sync_api import sync_playwright
    except ImportError:
        raise ValidationError('PLAYWRIGHT_REQUIRED: установите sarex-loader[browser].') from None
    from sarex_loader.tree_source import add_response

    if not sys.stdin.isatty():
        raise ValidationError('BROWSER_LOGIN_REQUIRES_TERMINAL: войдите вручную в окне Chrome.')
    phase = 'LAUNCH'
    try:
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch(
                channel='chrome', headless=False, chromium_sandbox=True)
            try:
                context = browser.new_context(service_workers='block', accept_downloads=False)
                context.set_default_timeout(30000)
                current_folder = min(root for root, _ in paths)

                def guard(route):
                    if scoped_browser_request_allowed(
                            route.request, source.disk_id, current_folder):
                        route.continue_()
                    else:
                        route.abort()

                context.route('**/*', guard)
                context.route_web_socket('**/*', lambda ws: ws.close())
                page = context.new_page()
                deadline = time.monotonic() + 1800
                total_bytes = 0
                print('Войдите вручную в отдельном окне Chrome. '
                      'После входа дерево будет прочитано автоматически; '
                      'документы и папки не изменяются.', file=sys.stderr)
                first_root = min(root for root, _ in paths)
                phase = 'LOGIN_UI'
                page.goto(f'{UI_ORIGIN}/documentations/{first_root}',
                          wait_until='domcontentloaded', timeout=45000)
                # A menu is only a navigation signal, not proof of authentication
                # or a loaded Documentation module. Access is proved below by a
                # validated Gateway response for the requested folder.
                page.locator('a[href="/documentations"], '
                             'a[href="https://lk.sarex.io/documentations"]').first.wait_for(
                                 state='visible', timeout=300000)

                def fetch(folder):
                    nonlocal total_bytes, current_folder, phase
                    current_folder = folder
                    phase = 'GATEWAY_RESPONSE'
                    if time.monotonic() >= deadline:
                        raise ValidationError('TREE_TIME_BUDGET_EXCEEDED')
                    with page.expect_response(
                            lambda r: gateway_response_matches(r, source.disk_id, folder),
                            timeout=30000) as pending:
                        page.goto(f'{UI_ORIGIN}/documentations/{folder}',
                                  wait_until='domcontentloaded', timeout=45000)
                    response = pending.value
                    phase = 'GATEWAY_BODY'
                    if response.status != 200 or response.request.redirected_from is not None:
                        raise ValidationError('TREE_HTTP_REJECTED: требуется проверка доступа.')
                    mime = response.header_value('content-type') or ''
                    if not re.fullmatch(r'application/json(?:\s*;\s*charset=utf-8)?',
                                        mime, re.IGNORECASE):
                        raise ValidationError('TREE_CONTENT_TYPE_INVALID')
                    length = response.header_value('content-length')
                    if length is not None and (not length.isascii() or not length.isdecimal()
                                               or int(length) > source.max_response_bytes):
                        raise ValidationError('TREE_RESPONSE_TOO_LARGE')
                    raw = response.body()
                    total_bytes += len(raw)
                    if total_bytes > 128 * 1024**2:
                        raise ValidationError('TREE_TOTAL_RESPONSE_LIMIT')
                    add_response(index, raw, source.max_response_bytes, queried_folder=folder)

                collect_paths(paths, index, fetch, max_folders=source.max_folders)
                index.network_enabled = True
                context.close()
            finally:
                browser.close()
    except ValidationError:
        raise
    except Exception:
        # Playwright exceptions can contain URLs/query strings; never print them.
        raise ValidationError(f'BROWSER_TREE_FAILED[{phase}]: проверьте Chrome, вход, '
                              'модуль документации, disk_id и доступ; '
                              'автоматического повтора нет.') from None


def collect_subtrees(root_ids, index, fetch, *, max_folders):
    """BFS of observed direct child folders, including newly created months.

    Breadcrumb siblings and PDF objects never become navigation targets. The existing
    resolver validates every parent chain and conflicting observations fail closed.
    """
    if (not root_ids or any(not valid_id(i) for i in root_ids)
            or len(set(root_ids)) != len(root_ids)):
        raise ValidationError('TREE_ROOTS_INVALID')
    queue = deque((root, root) for root in sorted(root_ids))
    visited = set()
    while queue:
        folder, root = queue.popleft()
        if folder in visited:
            continue
        if len(visited) >= max_folders:
            raise ValidationError('TREE_FOLDER_BUDGET_EXCEEDED')
        if folder != root and root not in index.documents[folder].path_ids[:-1]:
            raise ValidationError('TREE_SCOPE_ESCAPE')
        fetch(folder)
        visited.add(folder)
        for child in sorted(index.children.get(folder, {}).values(), key=lambda d: d.id):
            if child.is_folder:
                queue.append((child.id, root))
    # A response may mention deep descendants without their direct parents. Such
    # objects are useful observations but cannot prove a complete traversal.
    if any(d.is_folder and any(root in d.path_ids for root in root_ids)
           and d.id not in visited for d in index.documents.values()):
        raise ValidationError('TREE_UNREACHABLE_FOLDER')
    return len(visited)


def collect_extension_tree(source, paths, index):
    from sarex_loader.browser_extension import ExtensionReader
    from sarex_loader.tree_source import add_response, observation_time

    if any(root not in source.root_ids for root, _ in paths):
        raise ValidationError('TREE_ROOT_NOT_CONFIGURED')
    started = datetime.now(UTC).isoformat()
    deadline = time.monotonic() + 3600
    total = 0
    observation = {'version': 1, 'disk_id': source.disk_id, 'root_ids': list(source.root_ids),
                   'started_at': started, 'queried_at': {}, 'blocked_mutations': 0,
                   'coverage': 'TRAVERSED_OBSERVED_FOLDERS', 'server_completeness': 'UNKNOWN'}
    with ExtensionReader(source.disk_id, source.max_response_bytes) as reader:
        def fetch(folder):
            nonlocal total
            if time.monotonic() >= deadline:
                raise ValidationError('TREE_TIME_BUDGET_EXCEEDED')
            try:
                value = reader.fetch(folder)
            except ValidationError as error:
                raise ValidationError(f'{error} [folder_id={folder}]') from None
            if (value['folder_id'] != folder or type(value['folder_id']) is not int
                    or value['status'] != 200 or type(value['blocked_mutations']) is not int
                    or value['blocked_mutations'] < observation['blocked_mutations']
                    or not observation_time(started) <= observation_time(value['received_at'])
                    <= datetime.now(UTC)):
                raise ValidationError('TREE_EXTENSION_RESPONSE_INVALID')
            raw = json.dumps(value['payload'], ensure_ascii=False, allow_nan=False).encode()
            total += len(raw)
            if total > 128 * 1024**2:
                raise ValidationError('TREE_TOTAL_RESPONSE_LIMIT')
            add_response(index, raw, source.max_response_bytes, queried_folder=folder)
            observation['queried_at'][str(folder)] = value['received_at']
            observation['blocked_mutations'] = value['blocked_mutations']
            if len(observation['queried_at']) % 10 == 0:
                print(f"Прочитано папок: {len(observation['queried_at'])}; "
                      f"объектов: {len(index.documents)}.", file=sys.stderr)

        collect_subtrees(source.root_ids, index, fetch, max_folders=source.max_folders)
    observation['finished_at'] = datetime.now(UTC).isoformat()
    index.observation = observation
    index.network_enabled = True
